/// <summary>
/// The data of one <see cref="DeprecatedUniqueType"/>: the unique text, the <c>@Deprecated(replaceWith=...)</c> expression
/// (<c>replacementText</c>; alternatives are separated by <c>" OR "</c>) and the flags. Kotlin's <c>targets</c> and
/// <c>docDescription</c> are "retained for copy-paste compatibility; unused at runtime" and not ported.
/// </summary>
public sealed record DeprecatedUniqueTypeEntry(DeprecatedUniqueType Type, string Text, IReadOnlySet<UniqueFlag>? FlagSet, string ReplaceWith)
{
    public IReadOnlySet<UniqueFlag> Flags => FlagSet ?? EmptyFlags;

    /// <summary>Kotlin <c>placeholderText</c>: the text with the parameters blanked out.</summary>
    public string PlaceholderText { get; } = Text.GetPlaceholderText();

    private static readonly IReadOnlySet<UniqueFlag> EmptyFlags = new HashSet<UniqueFlag>();
}

